import{_ as s,o as a,c as t,a4 as n}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"status","description":"","frontmatter":{},"headers":[],"relativePath":"cli/status.md","filePath":"cli/status.md","lastUpdated":null}'),o={name:"cli/status.md"};function r(i,e,l,c,d,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;status&quot;">​</a></h1><p><strong>Main entry point for web producers.</strong> Run <strong><code>make status</code></strong> first. If you have no configuration yet, status runs the setup wizard directly (brand, data source, OCAPI) so you can sign in and configure in one go, then continues to the hub. When status then finds no refreshes, it runs a pull and re-checks SFCC so LIVE/SYNCED appear. Interactive hub: pick refresh → pick action → run → back to board. <strong><code>make pull</code></strong> fetches data and auto-builds, then opens this same hub. If you run <strong><code>make status</code></strong> and there are no refreshes yet, status runs a pull for you and then shows the board.</p><p>Unified refresh dashboard for the active brand. Shows a short, focused list and lets you pick a refresh and run an action. Refresh labels include the go-live time from the campaign (e.g. <strong>r1 - 3pm</strong>, <strong>r2 - 3am</strong>).</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Last 14 days + future; interactive hub with loop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Show full list (no date window)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PULL=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # Bypass throttles (pull when no dates; force SFCC check)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Note: <code>make status --pull</code> does not work — <code>make</code> treats <code>--pull</code> as its own flag. Use <strong><code>make status PULL=1</code></strong> instead.</p><p>When there are <strong>no refreshes</strong>, status runs a pull for you and then shows the board — but only if the last such pull was more than 30 minutes ago (throttled, no message). Use <strong><code>make status PULL=1</code></strong> to run pull anyway or to force a fresh SFCC sync check.</p><p><strong>LIVE / SYNCED vs READY:</strong> Rows show <strong>READY</strong> when the refresh is built locally but not yet pushed to SFCC. After you push (or after campaigns already exist on SFCC), status checks SFCC and upgrades those rows to <strong>SYNCED</strong> or <strong>LIVE</strong> and stores that in the refresh.json sync section. That SFCC check runs when you open status if (1) you use <strong><code>make status PULL=1</code></strong>, or (2) no row is yet SYNCED/LIVE (so we try once to discover them), or (3) the last check was over 30 minutes ago. If you expect SYNCED/LIVE but only see READY, run <strong><code>make status PULL=1</code></strong> to force the check.</p><h2 id="date-window" tabindex="-1">Date window <a class="header-anchor" href="#date-window" aria-label="Permalink to &quot;Date window&quot;">​</a></h2><p>By default only refreshes from the <strong>last 14 days</strong> through <strong>all future</strong> dates are shown, so you don&#39;t scroll through a long list of past dates. Use <code>make status ALL=1</code> to see every refresh.</p><h2 id="current-live-and-time-ranges" tabindex="-1">Current live and time ranges <a class="header-anchor" href="#current-live-and-time-ranges" aria-label="Permalink to &quot;Current live and time ranges&quot;">​</a></h2><p><strong>Current live</strong> is the one refresh on the homepage right now, by time window. When the wireframe (Excel) has both start and end times, status finds the refresh whose window contains the current time; that row is marked <strong>(homepage now)</strong> and shown as LIVE. At most one row is LIVE.</p><p>When a refresh has both <strong>start and end</strong> times, the board shows a <strong>time range</strong> on the row (e.g. <code>2/13 3pm – 2/15 12am</code>) instead of a single date. That explains why there might be no row for a given calendar day—another refresh’s window covers that period. When Excel has start/end set, the board shows these ranges.</p><h2 id="interactive-hub" tabindex="-1">Interactive Hub <a class="header-anchor" href="#interactive-hub" aria-label="Permalink to &quot;Interactive Hub&quot;">​</a></h2><p>When you run <code>make status</code> in a terminal, it opens an interactive hub that loops:</p><ol><li><strong>Refresh picker</strong> — LIVE (homepage now) is first, then your selected refresh, then the rest. Each row shows date, refresh label with time (e.g. <code>r1 - 3pm</code>), name, and status. The row you&#39;re working on is marked <strong>← selected</strong>; the one on the site now is <strong>(homepage now)</strong>.</li><li><strong>Action picker</strong> — After selecting a refresh, choose an action: <ul><li><strong>Browse files</strong> — Build/compose if needed, then show one file browser (data, templates, rendered)</li><li><strong>Push to staging</strong> — Sync to SFCC staging</li><li><strong>Commit to Git</strong> — Commit changes to Git</li><li><strong>Rebuild (force)</strong> — Force rebuild ignoring guards</li><li><strong>Generate email</strong> — Generate changeout email</li><li><strong>Pull (refresh data)</strong> — Re-fetch data and auto-build new dates, then refresh the board</li></ul></li><li><strong>Action execution</strong> — Runs the selected action</li><li><strong>Return to board</strong> — After action completes, returns to refresh picker</li></ol><p>Pressing <code>q</code> on the action picker returns to the refresh picker. Pressing <code>q</code> on the refresh picker exits.</p><p>Picking a refresh sets it as active; subsequent commands (<code>make build</code>, <code>make preview</code>, etc.) use it automatically.</p><h2 id="no-tty-fallback" tabindex="-1">No-TTY fallback <a class="header-anchor" href="#no-tty-fallback" aria-label="Permalink to &quot;No-TTY fallback&quot;">​</a></h2><p>When status runs without a TTY (e.g. piped output or CI), it falls back to a table view: Date, Name, Status, Next Step, plus registry summary and footer. The Next Step column shows go-live time when relevant (e.g. <code>→ live 2/12 12 AM</code>). No interactive hub is shown.</p><p>For scripts: <code>make status ARGS=&quot;--no-interactive&quot;</code> forces table-only output even in a TTY. When running push from scripts or CI, use <code>--yes</code> (or <code>YES=1</code>) to skip confirmation prompts (e.g. data quality warnings).</p><h3 id="replay-one-action-by-index" tabindex="-1">Replay (one action by index) <a class="header-anchor" href="#replay-one-action-by-index" aria-label="Permalink to &quot;Replay (one action by index)&quot;">​</a></h3><p>When running non-interactively, you can run <strong>one</strong> action and exit by setting:</p><ul><li><code>STATUS_REFRESH_INDEX</code> — index of the refresh in the list (0-based)</li><li><code>STATUS_ACTION_INDEX</code> — index of the action. Order is defined in <code>src/cli/commands/statusInteractive.js</code> (STATUS_ACTIONS): 0 = Browse files, 1 = Push to staging, 2 = Commit to Git, 3 = Rebuild (force), 4 = Generate email, 5 = View data quality, 6 = Pull (refresh data)</li></ul><p>Example: <code>STATUS_REFRESH_INDEX=2 STATUS_ACTION_INDEX=1 make status</code> selects the third refresh, runs Push, then exits. This is for scripts and tests; normal <code>make status</code> usage is unchanged.</p><h3 id="example-tty-interactive-picker" tabindex="-1">Example: TTY (interactive picker) <a class="header-anchor" href="#example-tty-interactive-picker" aria-label="Permalink to &quot;Example: TTY (interactive picker)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━</span></span>
<span class="line"><span>  LOFT | STATUS                                          Fri, Feb 14</span></span>
<span class="line"><span>━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━</span></span>
<span class="line"><span>  ● LIVE · ✔ SYNC · ↻ UPD · ✔ READY · ○ BUILD · · NEW</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ↑↓ select · Enter action · q exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    2/12 7pm – 2/12 7pm  2/13 @3PM: FP 40 + EXTRA  ● LIVE   (homepage now)</span></span>
<span class="line"><span>  ❯ 2/14 7pm – 2/14 7pm  2/15: FP 40  / NFP 70     ✔ SYNCED</span></span>
<span class="line"><span>    2/16 7pm – 2/16 7pm  2/17: MARCH BOM           ✔ SYNCED  ← selected</span></span>
<span class="line"><span>    2/18 7pm – 2/18 7pm  2/19: STYLE EVENT         ✔ READY</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="example-non-tty-table-output" tabindex="-1">Example: non-TTY (table output) <a class="header-anchor" href="#example-non-tty-table-output" aria-label="Permalink to &quot;Example: non-TTY (table output)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ make status ARGS=&quot;--no-interactive&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Date                    Name                    Status              Next Step</span></span>
<span class="line"><span>  ─────────────────────────────────────────────────────────────────────────────</span></span>
<span class="line"><span>  2026-02-12 r1 - 3am     Post-V-Day Sale         ● LIVE              ✓ done</span></span>
<span class="line"><span>  2026-02-14 r1 - 3pm     Valentine&#39;s Day         ✔ READY             make push</span></span>
<span class="line"><span>  2026-02-15 r1 - 3am     Post-Valentine          ○ BUILD             make preview</span></span>
<span class="line"><span>  2026-02-20 r1 - 3pm     Presidents Day          · NEW               make preview</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="sync-state-and-ocapi" tabindex="-1">Sync state and OCAPI <a class="header-anchor" href="#sync-state-and-ocapi" aria-label="Permalink to &quot;Sync state and OCAPI&quot;">​</a></h2><p>When OCAPI is enabled, <strong><code>make status</code> uses SFCC as the source of truth for sync state:</strong></p><ul><li>Refreshes that have no local sync record but exist on SFCC are shown as SYNCED/LIVE and local state is updated.</li><li>Refreshes that are marked SYNCED/LIVE locally are checked against SFCC; if the campaign no longer exists on SFCC, state is downgraded to READY and local sync config is updated.</li></ul><p>So after cloning the repo or moving to another machine, running <code>make status</code> once will align the dashboard with what’s actually on SFCC.</p><h3 id="ocapi-best-practices-throttling" tabindex="-1">OCAPI best practices (throttling) <a class="header-anchor" href="#ocapi-best-practices-throttling" aria-label="Permalink to &quot;OCAPI best practices (throttling)&quot;">​</a></h3><p>Per <a href="https://resources.docs.salesforce.com/rel1/doc/en-us/static/pdf/OCAPIPerformanceBestPracticesExternalFAQ.pdf" target="_blank" rel="noreferrer">Salesforce OCAPI Performance Best Practices</a>, Data API requests cannot be cached by the platform and should be used sparingly. To limit load:</p><ul><li><strong>SFCC check is throttled</strong> — Status only calls the Data API (enrich/verify campaigns) at most once every <strong>30 minutes</strong>. Other runs use the last known local sync state.</li><li><strong>Override</strong> — Use <strong><code>make status PULL=1</code></strong> to force a fresh SFCC check (and, when there are no dates, to run pull). Optional env: <code>STATUS_SFCC_CHECK_COOLDOWN_MS</code> to change the throttle window.</li></ul><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Condition</th></tr></thead><tbody><tr><td><code>LIVE</code></td><td>Synced and on site now: folder date is today, or current time is inside the refresh’s start–end window (folder = nominal start; end shows the span)</td></tr><tr><td><code>SYNCED</code></td><td>Synced but not currently live (outside window and/or date not today)</td></tr><tr><td><code>UPDATED</code></td><td>Previously synced but new source data since last push (needs rebuild)</td></tr><tr><td><code>READY</code></td><td><code>ocapi-payload.json</code> exists, not yet pushed</td></tr><tr><td><code>BUILD</code></td><td><code>refresh.json</code> exists but no payload</td></tr><tr><td><code>NEW</code></td><td>Data fetched, not yet built (same as BUILD)</td></tr></tbody></table><p>Definitions are canonical in <a href="/ocapi-docs.github.io/glossary.html#status-states">Glossary — Status States</a>. Status uses <strong>local</strong> sync state first (from the refresh.json sync section in each refresh folder). When <strong>OCAPI is enabled</strong>, it also checks SFCC: if a refresh&#39;s campaign exists on the site, that row is shown as SYNCED or LIVE even when local state is missing (e.g. after deleting dev-env). Any state learned from SFCC is <strong>written back to local</strong> automatically, so the next run (or build guards) can use it without re-querying SFCC.</p><h2 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h2><p>Use the Makefile for all commands:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ARGS=&quot;--help&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Direct <code>node src/cli/index.js status --help</code> is for debugging and scripting only.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/cli/">CLI Reference</a> — all producer and dev commands</li><li><a href="/ocapi-docs.github.io/cli/pull.html">pull</a></li><li><a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer workflow</a></li></ul>`,45)])])}const g=s(o,[["render",r]]);export{u as __pageData,g as default};
